#include "expression_reduction_internal.hpp"
#include "qupathxx/project.hpp"
#include "workflow_input.hpp"
#include "spatial_output_guard.hpp"
#include <set>

namespace qpx {
using namespace detail::reduction;
namespace {
void workflow_options(const ExpressionReductionWorkflowOptions& o){work_limit(o.work_bytes);if(!o.image || !o.project_bytes || o.project_bytes>4ull*1024*1024*1024 || o.snapshot_bytes<1024*1024 || o.snapshot_bytes>1024ull*1024*1024)throw std::invalid_argument("Invalid reduction workflow image/save limits");}
}
std::shared_ptr<const ExpressionReductionResult> run_expression_reduction(const std::string& input,const std::string& output,const ExpressionReductionWorkflowOptions& o,const std::atomic<bool>* cancelled){
    workflow_options(o);digest(o.matrix_id);if(!o.record_id.empty())throw std::invalid_argument("New reduction does not accept a replay record");const auto destination=detail::export_path(output);if(std::filesystem::exists(std::filesystem::u8path(destination)))throw WorkflowOutputExists("Reduction output project already exists");
    const detail::WorkflowInput project_file(input,o.project_bytes,true,cancelled),spec_file(o.spec_path,4u*1024*1024,false,cancelled);std::size_t reserved=8u*1024*1024;charge(reserved,std::size_t(spec_file.bytes()),64,o.work_bytes);if(o.work_bytes-reserved<32u*1024*1024)throw WorkflowCaptureLimit("Reduction specification leaves less than32MiB analysis workspace");
    const auto project=Project::open(project_file.path());const auto source=reopen_expression_matrix(*project,o.image,o.matrix_id,o.work_bytes,cancelled);const auto spec=read_workflow_input(spec_file,cancelled);const auto j=J::parse(spec,[](int depth,J::parse_event_t,J&){if(depth>8)throw std::invalid_argument("Reduction specification nesting exceeds8");return true;});
    const std::set<std::string> allowed{"schema","method","features","normalization","components","oversampling","power_iterations","clusters","seed","max_iterations","cluster_tolerance"};if(!j.is_object() || j.at("schema")!="qpx.expression-reduction-spec/1")throw std::invalid_argument("Invalid reduction specification schema");for(auto i=j.begin();i!=j.end();++i)if(!allowed.count(i.key()))throw std::invalid_argument("Unknown reduction specification key: "+i.key());ExpressionReductionOptions options;options.work_bytes=o.work_bytes-reserved;options.max_operations=o.max_operations;options.max_distance_tests=o.max_distance_tests;
    const auto method=j.at("method").get<std::string>();if(method=="uncentered-svd")options.center=false;else if(method!="centered-pca")throw std::invalid_argument("Select centered-pca or uncentered-svd explicitly");options.clusters=std::uint32_t(integer(j.at("clusters"),32));
    if(j.contains("features")){const auto& ids=j.at("features");if(!ids.is_array() || ids.empty() || ids.size()>1000000)throw std::invalid_argument("Reduction explicit features require a nonempty bounded ID array");for(const auto& id:ids){const auto f=source->feature_index(id.get<std::string>(),cancelled);if(!f)throw std::invalid_argument("Reduction feature ID absent");options.features.push_back(*f);}std::sort(options.features.begin(),options.features.end());if(std::adjacent_find(options.features.begin(),options.features.end())!=options.features.end())throw std::invalid_argument("Duplicate reduction feature ID");}
    if(j.contains("normalization"))options.normalization_recipe=expression_normalization_recipe(*project,o.image,j.at("normalization").get<std::string>());
    if(j.contains("components"))options.components=std::uint32_t(integer(j.at("components"),32));if(j.contains("oversampling"))options.oversampling=std::uint32_t(integer(j.at("oversampling"),32));if(j.contains("power_iterations"))options.power_iterations=std::uint32_t(integer(j.at("power_iterations"),4));if(j.contains("seed"))options.seed=integer(j.at("seed"),UINT64_MAX);if(j.contains("max_iterations"))options.max_iterations=std::uint32_t(integer(j.at("max_iterations"),1000));if(j.contains("cluster_tolerance")){if(!j.at("cluster_tolerance").is_number())throw std::invalid_argument("Reduction tolerance must be numeric");options.cluster_tolerance=j.at("cluster_tolerance").get<double>();}
    const auto result=reduce_expression(source,options,cancelled);const auto bytes=ExpressionReductionCodec::encode(*result,o.work_bytes,cancelled);Sha256 hash;hash.update(bytes.data(),bytes.size());const auto file_hash=hash.finish();const auto folder=std::filesystem::u8path(destination).parent_path()/".qpx-expression-reductions";if(std::filesystem::is_symlink(std::filesystem::symlink_status(folder)))throw std::invalid_argument("Reduction output folder is linked");
#ifdef _WIN32
    const auto attributes=GetFileAttributesW(folder.c_str());if(attributes!=INVALID_FILE_ATTRIBUTES && (attributes&FILE_ATTRIBUTE_REPARSE_POINT))throw std::invalid_argument("Reduction output folder is a reparse point");
#endif
    std::filesystem::create_directories(folder);const auto archive=(folder/(file_hash+".qpr")).u8string();if(std::filesystem::exists(std::filesystem::u8path(archive))){const detail::WorkflowInput previous(archive,archive_limit,false,cancelled);if(previous.sha256()!=file_hash)throw WorkflowInputChanged("Existing fitted archive differs");}else save_expression_reduction_archive(*result,archive,o.work_bytes,cancelled);
    const auto guard=[&]{project_file.verify(false,cancelled);spec_file.verify(false,cancelled);source->require_current(cancelled);detail::protect_spatial_path(project_file.path(),"",destination);detail::protect_spatial_path(source->path(),"",destination);detail::protect_spatial_path(spec_file.path(),"",destination);detail::protect_spatial_path(archive,"",destination);};guard();keep_expression_reduction(*project,o.image,*result,archive,true,o.work_bytes,cancelled);project->save_new(destination,o.snapshot_bytes,o.project_bytes,cancelled,guard);return result;
}
std::shared_ptr<const ExpressionReductionResult> open_project_expression_reduction(const std::string& input,const ExpressionReductionWorkflowOptions& o,bool replay,const std::atomic<bool>* cancelled){workflow_options(o);digest(o.record_id);if(!o.matrix_id.empty() || !o.spec_path.empty())throw std::invalid_argument("Reduction opening accepts a retained record instead of a new matrix/specification");const detail::WorkflowInput file(input,o.project_bytes,true,cancelled);const auto project=Project::open(file.path());const auto request=expression_reduction_open_request(*project,o.image,o.record_id);const auto result=request.open(o.work_bytes,cancelled);if(replay)replay_expression_reduction(request.parent.open(o.work_bytes,cancelled),*result,o.work_bytes,cancelled,o.max_operations,o.max_distance_tests);file.verify(false,cancelled);return result;}
}
